<?php
declare(strict_types=1);
require_once __DIR__.'/../auth_check.php';
AccessManager::requirePageAccess('devis/transfert_financier.php');
require_once __DIR__.'/../model/Database.php';
require_once __DIR__.'/../services/DevisFinancialTransferService.php';
$pdo=Database::getConnection();$service=new DevisFinancialTransferService($pdo);
$_SESSION['devis_transfer_csrf']=$_SESSION['devis_transfer_csrf']??bin2hex(random_bytes(32));
$sourceId=(int)($_REQUEST['source_devis_id']??0);$targetId=(int)($_REQUEST['target_devis_id']??0);
$source=$target=null;$success='';$error='';
try {if($sourceId)$source=$service->describe($sourceId);if($targetId)$target=$service->describe($targetId);}catch(Throwable $e){$error=$e->getMessage();}
if($_SERVER['REQUEST_METHOD']==='POST'&&($_POST['action']??'')==='execute'){
 try{
  if(!hash_equals((string)$_SESSION['devis_transfer_csrf'],(string)($_POST['_csrf']??'')))throw new DomainException('Session expirée. Rechargez la page.');
  if(empty($_POST['confirmed']))throw new DomainException('Confirmez avoir vérifié toutes les correspondances.');
  $lineMap=array_map('intval',(array)($_POST['line_map']??[]));$debMap=array_map('intval',(array)($_POST['debourse_map']??[]));
  $result=$service->transfer($sourceId,$targetId,$lineMap,$debMap,!empty($_POST['move_sites']),(string)($_POST['reason']??''),(int)($_SESSION['user_id']??0));
  $success='Transfert #'.$result['transfer_id'].' terminé : '.$result['moved_lines'].' ligne(s) et '.$result['moved_debourses'].' déboursé(s) contrôlés. Le devis source est maintenant archivable.';
  $source=$service->describe($sourceId);$target=$service->describe($targetId);
 }catch(Throwable $e){$error=$e->getMessage();}
}
$quotes=$service->quotes();$history=$service->history();$h=static fn($v)=>htmlspecialchars((string)$v,ENT_QUOTES,'UTF-8');
$pageTitle='Fusion financière de devis';$activeMenu='module_devis_list';
require_once __DIR__.'/../decaissement/includes/header.php';require_once __DIR__.'/../decaissement/includes/navbar.php';
?>
