<header class="rounded-3xl bg-gradient-to-br from-slate-950 via-slate-900 to-teal-800 p-7 text-white shadow-xl"><div class="flex flex-wrap items-center justify-between gap-5"><div><p class="text-xs font-black uppercase tracking-[.2em] text-amber-300">FINEA · Centre devis</p><h1 class="mt-2 text-3xl font-black">Fusionner l’historique financier</h1><p class="mt-2 max-w-3xl text-slate-200">Assistant sécurisé pour corriger un doublon sans perdre les liens entre lignes, déboursés, FEB, fiches de décaissement et chantiers.</p></div><a href="liste.php" class="rounded-xl border border-white/20 bg-white/10 px-5 py-3 font-bold"><i class="fas fa-list mr-2"></i>Liste des devis</a></div></header>
<?php if($success):?><div class="mt-5 rounded-2xl border border-emerald-200 bg-emerald-50 p-5 font-bold text-emerald-900"><i class="fas fa-circle-check mr-2"></i><?=$h($success)?> <a class="ml-3 underline" href="liste.php?archive_status=active&focus=<?=$sourceId?>">Voir le devis source</a></div><?php endif;?>
<?php if($error):?><div class="mt-5 rounded-2xl border border-rose-200 bg-rose-50 p-5 font-bold text-rose-900"><i class="fas fa-triangle-exclamation mr-2"></i><?=$h($error)?></div><?php endif;?>
<section class="mt-6 rounded-2xl border border-slate-200 bg-white p-6 shadow-sm"><div class="mb-5"><h2 class="text-xl font-black text-slate-950">1. Choisir le doublon et le devis à conserver</h2><p class="text-sm text-slate-500">Par sécurité, les deux devis doivent appartenir au même client et au même projet.</p></div>
<form method="get" class="grid gap-4 lg:grid-cols-[1fr_auto_1fr_auto] lg:items-end">
<?php foreach(['source'=>'Devis source à vider','target'=>'Devis cible à conserver'] as $key=>$label): $selectedId=$key==='source'?$sourceId:$targetId;?><label class="text-sm font-bold text-slate-700"><?=$label?><select name="<?=$key?>_devis_id" required class="mt-2 w-full rounded-xl border border-slate-300 bg-white px-4 py-3 searchable"><option value="">Rechercher par numéro, projet ou client…</option><?php foreach($quotes as $q):?><option value="<?=(int)$q['id']?>" <?=$selectedId===(int)$q['id']?'selected':''?>><?=$h($q['numero_devis'].' · '.$q['projet'].' · '.$q['client'].' · '.number_format((float)$q['total_ttc'],0,',',' ').' FCFA')?></option><?php endforeach;?></select></label><?php if($key==='source'):?><div class="hidden pb-3 text-2xl text-slate-300 lg:block"><i class="fas fa-arrow-right"></i></div><?php endif;?><?php endforeach;?>
<button class="rounded-xl bg-slate-950 px-5 py-3 font-black text-white"><i class="fas fa-magnifying-glass mr-2"></i>Préparer</button></form></section>
<?php if($source&&$target):?>
<form method="post" id="transfer-form" class="mt-6 space-y-6"><input type="hidden" name="_csrf" value="<?=$h($_SESSION['devis_transfer_csrf'])?>"><input type="hidden" name="action" value="execute"><input type="hidden" name="source_devis_id" value="<?=$sourceId?>"><input type="hidden" name="target_devis_id" value="<?=$targetId?>">
<section class="grid gap-5 xl:grid-cols-2"><article class="rounded-2xl border-2 border-rose-200 bg-white p-5"><span class="rounded-full bg-rose-100 px-3 py-1 text-xs font-black uppercase text-rose-800">Source · sera vidé</span><h3 class="mt-3 text-xl font-black"><?=$h($source['quote']['numero_devis'])?></h3><p class="text-sm text-slate-500"><?=count($source['lines'])?> ligne(s) · <?=count($source['debourses'])?> déboursé(s)</p></article><article class="rounded-2xl border-2 border-emerald-200 bg-white p-5"><span class="rounded-full bg-emerald-100 px-3 py-1 text-xs font-black uppercase text-emerald-800">Cible · sera conservé</span><h3 class="mt-3 text-xl font-black"><?=$h($target['quote']['numero_devis'])?></h3><p class="text-sm text-slate-500"><?=count($target['lines'])?> ligne(s) · <?=count($target['debourses'])?> déboursé(s)</p></article></section>
<section class="rounded-2xl border bg-white p-6 shadow-sm"><h2 class="text-xl font-black">2. Correspondance des lignes de devis</h2><p class="mb-5 text-sm text-slate-500">« Ajouter à la cible » conserve la ligne et son identifiant. Choisissez une ligne existante seulement s’il s’agit réellement du même poste.</p><div class="overflow-x-auto"><table class="w-full min-w-[900px] text-left text-sm"><thead class="bg-slate-950 text-white"><tr><th class="p-3">Ligne source</th><th class="p-3">Montant</th><th class="p-3">Déboursés</th><th class="p-3">Destination</th></tr></thead><tbody><?php foreach($source['lines'] as $l):?><tr class="border-b"><td class="p-3 font-bold"><?=$h($l['designation'])?> <small class="text-slate-400">#<?=(int)$l['id']?></small></td><td class="p-3"><?=number_format((float)$l['total'],0,',',' ')?> FCFA</td><td class="p-3"><?=(int)$l['debourse_count']?></td><td class="p-3"><select name="line_map[<?=(int)$l['id']?>]" class="w-full rounded-xl border px-3 py-2"><option value="0">＋ Ajouter cette ligne au devis cible</option><?php foreach($target['lines'] as $tl):?><option value="<?=(int)$tl['id']?>">Fusionner avec : <?=$h($tl['designation'])?> (#<?=(int)$tl['id']?>)</option><?php endforeach;?></select></td></tr><?php endforeach;?></tbody></table></div></section>
<section class="rounded-2xl border bg-white p-6 shadow-sm"><h2 class="text-xl font-black">3. Correspondance des déboursés</h2><p class="mb-5 text-sm text-slate-500">Par défaut chaque déboursé est conservé et déplacé. Une fusion déplace ses lignes vers le déboursé cible sans casser les fiches existantes.</p><div class="grid gap-4 lg:grid-cols-2"><?php foreach($source['debourses'] as $d):?><label class="rounded-xl border bg-slate-50 p-4 text-sm font-bold"><span>Déboursé #<?=(int)$d['id']?> · <?=number_format((float)$d['montant_debourse'],0,',',' ')?> FCFA · <?=(int)$d['line_count']?> ligne(s)</span><select name="debourse_map[<?=(int)$d['id']?>]" class="mt-3 w-full rounded-xl border bg-white px-3 py-2"><option value="0">Déplacer comme déboursé distinct</option><?php foreach($target['debourses'] as $td):?><option value="<?=(int)$td['id']?>">Fusionner avec déboursé #<?=(int)$td['id']?> · <?=number_format((float)$td['montant_debourse'],0,',',' ')?> FCFA</option><?php endforeach;?></select></label><?php endforeach;?></div></section>
<section class="rounded-2xl border border-amber-200 bg-amber-50 p-6"><h2 class="text-xl font-black text-slate-950">4. Validation transactionnelle</h2><div class="mt-4 grid gap-4 lg:grid-cols-2"><label class="rounded-xl bg-white p-4 font-bold"><input type="checkbox" name="move_sites" value="1" checked class="mr-2">Rattacher les chantiers du devis source au devis cible</label><label class="text-sm font-bold">Motif de la fusion<input name="reason" required minlength="5" placeholder="Ex. Devis créé en doublon lors de l’import" class="mt-2 w-full rounded-xl border px-4 py-3"></label></div><label class="mt-4 block rounded-xl border border-amber-300 bg-white p-4 font-bold"><input type="checkbox" name="confirmed" value="1" required class="mr-2">J’ai vérifié les correspondances. Je confirme le transfert complet.</label><div class="mt-5 flex flex-wrap items-center justify-between gap-3"><p class="max-w-3xl text-sm text-amber-900"><i class="fas fa-shield-halved mr-2"></i>Tout est exécuté dans une seule transaction. Au moindre échec, aucun déplacement n’est conservé.</p><button class="rounded-xl bg-teal-700 px-6 py-3 font-black text-white" onclick="return confirm('Confirmer définitivement la fusion financière de ces deux devis ?')"><i class="fas fa-code-merge mr-2"></i>Exécuter la fusion</button></div></section>
</form><?php endif;?></div></main>
<section class="mx-auto mb-12 mt-6 max-w-[1500px] px-4"><div class="rounded-2xl border bg-white p-6 shadow-sm"><h2 class="text-xl font-black">Dernières fusions et tentatives</h2><p class="mb-4 text-sm text-slate-500">Chaque opération conserve son auteur, son motif, ses correspondances et son résultat.</p><div class="overflow-x-auto"><table class="w-full min-w-[760px] text-left text-sm"><thead class="bg-slate-100"><tr><th class="p-3">Date</th><th class="p-3">Source</th><th class="p-3">Cible</th><th class="p-3">Motif</th><th class="p-3">Auteur</th><th class="p-3">Résultat</th></tr></thead><tbody><?php foreach($history as $row):?><tr class="border-b"><td class="p-3"><?=$h(date('d/m/Y H:i',strtotime((string)$row['created_at'])))?></td><td class="p-3 font-bold"><?=$h($row['source_numero']??'#'.$row['source_devis_id'])?></td><td class="p-3 font-bold"><?=$h($row['target_numero']??'#'.$row['target_devis_id'])?></td><td class="p-3"><?=$h($row['reason'])?></td><td class="p-3"><?=$h($row['auteur']??'—')?></td><td class="p-3"><span class="rounded-full px-3 py-1 text-xs font-black <?=$row['status']==='completed'?'bg-emerald-100 text-emerald-800':($row['status']==='failed'?'bg-rose-100 text-rose-800':'bg-amber-100 text-amber-800')?>"><?=$row['status']==='completed'?'Réussie':($row['status']==='failed'?'Échec':'En cours')?></span></td></tr><?php endforeach;?><?php if(!$history):?><tr><td colspan="6" class="p-8 text-center text-slate-500">Aucune fusion enregistrée.</td></tr><?php endif;?></tbody></table></div></div></section>
<script>document.querySelectorAll('.searchable').forEach(s=>{s.addEventListener('change',()=>{const other=document.querySelector(s.name.startsWith('source')?'[name=target_devis_id]':'[name=source_devis_id]');if(s.value&&s.value===other.value){alert('La source et la cible doivent être différentes.');s.value=''}})});</script>
